1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  type EventTimelineItem,
4	  type ImageMessageContent,
5	  MessageType_Tags,
6	  MsgLikeKind_Tags,
7	  type RoomInterface,
8	  TimelineItemContent_Tags,
9	  type VideoMessageContent,
10	} from "@unomed/react-native-matrix-sdk";
11	import { useSetAtom } from "jotai";
12	import { TimelineAtoms } from "modules/timeline/jotai";
13	import { type FC, useMemo, useState } from "react";
14	import { StyleSheet } from "react-native";
15	import { useMediaTimeline } from "screens/room-media/hooks";
16	import { Button } from "shared/components";
17	import { Colors, TextSize } from "shared/styles";
18	import { FilesList } from "../files-list";
19	import { MediaList } from "../media-list";
20	
21	interface Props {
22	  room: RoomInterface;
23	}
24	
25	type Tab = "media" | "files";
26	
27	function isMediaItem(event: EventTimelineItem): boolean {
28	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
29	    const kind = event.content.inner.content.kind;
30	    if (kind?.tag === MsgLikeKind_Tags.Message) {
31	      const tag = kind.inner.content.msgType?.tag;
32	      return tag === MessageType_Tags.Image || tag === MessageType_Tags.Video;
33	    }
34	  }
35	  return false;
36	}
37	
38	function isFileItem(event: EventTimelineItem): boolean {
39	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
40	    const kind = event.content.inner.content.kind;
41	    if (kind?.tag === MsgLikeKind_Tags.Message) {
42	      const tag = kind.inner.content.msgType?.tag;
43	      return tag === MessageType_Tags.File || tag === MessageType_Tags.Audio;
44	    }
45	  }
46	  return false;
47	}
48	
49	export const MediaGallery: FC<Props> = ({ room }) => {
50	  const { mediaItems: allItems, loading } = useMediaTimeline({
51	    room,
52	    roomId: room.id(),
53	  });
54	  const [activeTab, setActiveTab] = useState<Tab>("media");
55	  const mediaItems = useMemo(() => allItems.filter(isMediaItem), [allItems]);
56	  const fileItems = useMemo(() => allItems.filter(isFileItem), [allItems]);
57	  const isMediaEmpty = !mediaItems.length;
58	  const isFileEmpty = !fileItems.length;
59	  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);
60	  const setVideoViewerPayload = useSetAtom(TimelineAtoms.videoViewerPayload);
61	
62	  const handleSetActiveImageUri = (
63	    uri: string | null,
64	    type?: "image" | "video",
65	    content?: ImageMessageContent | VideoMessageContent,
66	    event?: EventTimelineItem,
67	  ) => {
68	    if (!type) return;
69	    const roomId = room.id();
70	    if (type === "image" && uri) {
71	      setImageViewerPayload({ uri, event, roomId });
72	      return;
73	    }
74	    if (type === "video" && content) {
75	      setVideoViewerPayload({
76	        content: content as VideoMessageContent,
77	        event,
78	        roomId,
79	      });
80	    }
81	  };
82	
83	  return (
84	    <Block flex={1}>
85	      <Block flexDirection="row" margins={{ marginBottom: 16 }}>
86	        {(["media", "files"] as Tab[]).map((tab) => (
87	          <Button.Wrapper
88	            key={tab}
89	            onPress={() => setActiveTab(tab)}
90	            style={styles.tab}
91	          >
92	            <Block
93	              align="center"
94	              paddings={[10, 0]}
95	              border={{
96	                borderBottomWidth: 2,
97	                borderBottomColor:
98	                  activeTab === tab ? Colors.primary : Colors.white20,
99	              }}
100	            >
101	              <Text
102	                size={TextSize.small}
103	                color={activeTab === tab ? Colors.white : Colors.white50}
104	                textTransform="capitalize"
105	              >
106	                {tab}
107	              </Text>
108	            </Block>
109	          </Button.Wrapper>
110	        ))}
111	      </Block>
112	
113	      {activeTab === "media" ? (
114	        <Block flex={1}>
115	          <MediaList
116	            items={mediaItems}
117	            loading={loading}
118	            isEmpty={isMediaEmpty}
119	            onPressItem={handleSetActiveImageUri}
120	          />
121	        </Block>
122	      ) : (
123	        <FilesList items={fileItems} loading={loading} isEmpty={isFileEmpty} />
124	      )}
125	    </Block>
126	  );
127	};
128	
129	const styles = StyleSheet.create({
130	  tab: {
131	    flex: 1,
132	  },
133	});
