1	import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
2	import { ImageZoom } from "@likashefqet/react-native-image-zoom";
3	import { animateParallel, Block, Text } from "@prototyp/skeletor";
4	import { ProfileDetails_Tags } from "@unomed/react-native-matrix-sdk";
5	import { format } from "date-fns";
6	import { useAtom, useSetAtom } from "jotai";
7	import { TimelineAtoms } from "modules/timeline/jotai";
8	import type { FC } from "react";
9	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
10	import {
11	  Dimensions,
12	  Image,
13	  Modal,
14	  StyleSheet,
15	  TouchableOpacity,
16	} from "react-native";
17	import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
18	import { Colors, TextSize } from "shared/styles";
19	import {
20	  cacheImage,
21	  getCachedImagePathByURL,
22	} from "shared/utils/image-caching";
23	import { BlurGradientOverlay } from "../blur-gradient-overlay";
24	import { Button } from "../button";
25	import { Loading } from "../loading";
26	
27	const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
28	
29	const isLocalUri = (uri: string) => uri.startsWith("file://");
30	
31	export const ImageViewerModal: FC = () => {
32	  const [payload, setPayload] = useAtom(TimelineAtoms.imageViewerPayload);
33	  const [localUri, setLocalUri] = useState<string | null>(null);
34	  const [isLoading, setIsLoading] = useState(true);
35	  const [hasError, setHasError] = useState(false);
36	  const [showControls, setShowControls] = useState(true);
37	  const uri = payload?.uri ?? null;
38	  const event = payload?.event ?? null;
39	  const roomId = payload?.roomId ?? null;
40	  const visible = !!uri;
41	  const hasEventContext = !!event && !!roomId;
42	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
43	
44	  const senderName = useMemo(() => {
45	    if (!event) return null;
46	    if (event.senderProfile.tag === ProfileDetails_Tags.Ready) {
47	      return event.senderProfile.inner.displayName ?? event.sender;
48	    }
49	    return event.sender;
50	  }, [event]);
51	
52	  const formattedDate = useMemo(() => {
53	    if (!event) return null;
54	    return format(Number(event.timestamp), "MMM d, HH:mm");
55	  }, [event]);
56	
57	  const controlsAnimation = useRef(
58	    animateParallel(
59	      { translateY: [-120, 0], opacity: [0, 1] },
60	      { duration: 280 },
61	    ),
62	  ).current;
63	
64	  useEffect(() => {
65	    if (showControls) controlsAnimation.start();
66	    else controlsAnimation.reverse();
67	  }, [showControls]);
68	
69	  useEffect(() => {
70	    if (!uri) return;
71	
72	    let cancelled = false;
73	    setLocalUri(null);
74	    setIsLoading(true);
75	    setHasError(false);
76	
77	    const load = async () => {
78	      try {
79	        if (isLocalUri(uri)) {
80	          setLocalUri(uri);
81	          return;
82	        }
83	
84	        await cacheImage(uri);
85	        if (cancelled) return;
86	        setLocalUri(getCachedImagePathByURL(uri));
87	      } catch {
88	        if (cancelled) return;
89	        setIsLoading(false);
90	        setHasError(true);
91	      }
92	    };
93	
94	    load();
95	
96	    return () => {
97	      cancelled = true;
98	    };
99	  }, [uri]);
100	
101	  const onClose = useCallback(() => {
102	    setPayload(null);
103	    setLocalUri(null);
104	    setHasError(false);
105	    setIsLoading(true);
106	    setShowControls(true);
107	  }, [setPayload]);
108	
109	  const handleSingleTap = useCallback(() => {
110	    setShowControls((prev) => !prev);
111	  }, []);
112	
113	  const handleImageLoad = useCallback(() => {
114	    setIsLoading(false);
115	    setHasError(false);
116	  }, []);
117	
118	  const handleImageError = useCallback(() => {
119	    setIsLoading(false);
120	    setHasError(true);
121	  }, []);
122	
123	  const handleRetry = useCallback(async () => {
124	    if (!uri) return;
125	    setLocalUri(null);
126	    setIsLoading(true);
127	    setHasError(false);
128	
129	    try {
130	      if (isLocalUri(uri)) {
131	        setLocalUri(uri);
132	        return;
133	      }
134	
135	      await cacheImage(uri);
136	      setLocalUri(getCachedImagePathByURL(uri));
137	    } catch {
138	      setIsLoading(false);
139	      setHasError(true);
140	    }
141	  }, [uri]);
142	
143	  const handleOpenInfo = useCallback(() => {
144	    if (!event || !roomId) return;
145	    setImageInfoPayload({ event, roomId, localUri });
146	  }, [event, roomId, localUri, setImageInfoPayload]);
147	
148	  if (!visible) return null;
149	
150	  return (
151	    <Modal
152	      visible={visible}
153	      animationType="fade"
154	      statusBarTranslucent
155	      transparent
156	      onRequestClose={onClose}
157	    >
158	      <BottomSheetModalProvider>
159	        <Block
160	          background={Colors.black}
161	          flex={1}
162	          justify="center"
163	          align="center"
164	        >
165	          <Block
166	            absolute
167	            offsets={{ top: 0, left: 0, right: 0 }}
168	            zIndex={10}
169	            paddings={[56, 20, 16, 20]}
170	            flexDirection="row"
171	            align="center"
172	            justify="space-between"
173	            gap={12}
174	            background={Colors.primary}
175	            animations={controlsAnimation.animations}
176	            pointerEvents={showControls ? "auto" : "none"}
177	          >
178	            <BlurGradientOverlay />
179	            <Block width={60} align="flex-start" zIndex={2}>
180	              {hasEventContext && (
181	                <Button.Wrapper onPress={handleOpenInfo}>
182	                  <Image
183	                    source={require("assets/icons/info.png")}
184	                    style={styles.infoIcon}
185	                    tintColor={Colors.white}
186	                  />
187	                </Button.Wrapper>
188	              )}
189	            </Block>
190	            <Block flex={1} align="center" gap={2} zIndex={2}>
191	              {senderName && (
192	                <Text
193	                  color={Colors.white}
194	                  font="InstrumentSans-Semibold"
195	                  numberOfLines={1}
196	                >
197	                  {senderName}
198	                </Text>
199	              )}
200	              {formattedDate && (
201	                <Text
202	                  size={TextSize.tiny}
203	                  color={Colors.white80}
204	                  numberOfLines={1}
205	                >
206	                  {formattedDate}
207	                </Text>
208	              )}
209	            </Block>
210	            <Block width={60} align="flex-end" zIndex={2}>
211	              <Button.Wrapper onPress={onClose}>
212	                <Text font="InstrumentSans-Semibold" color={Colors.white}>
213	                  Close
214	                </Text>
215	              </Button.Wrapper>
216	            </Block>
217	          </Block>
218	
219	          <Block width={SCREEN_WIDTH} height={SCREEN_HEIGHT}>
220	            {isLoading && !hasError && (
221	              <Block
222	                absolute
223	                width={SCREEN_WIDTH}
224	                height={SCREEN_HEIGHT}
225	                align="center"
226	                justify="center"
227	                zIndex={5}
228	                background={Colors.white10}
229	              >
230	                <Loading isFullScreen={false} />
231	              </Block>
232	            )}
233	
234	            {hasError ? (
235	              <Block
236	                width={SCREEN_WIDTH}
237	                height={SCREEN_HEIGHT}
238	                align="center"
239	                justify="center"
240	              >
241	                <Text color={Colors.white}>Failed to load image</Text>
242	                <TouchableOpacity
243	                  onPress={handleRetry}
244	                  style={styles.retryButton}
245	                >
246	                  <Text size={TextSize.small} color={Colors.white}>
247	                    Tap to retry
248	                  </Text>
249	                </TouchableOpacity>
250	              </Block>
251	            ) : localUri ? (
252	              <ImageZoom
253	                key={localUri}
254	                uri={localUri}
255	                minScale={1}
256	                maxScale={5}
257	                maxPanPointers={2}
258	                isPanEnabled
259	                isPinchEnabled
260	                isDoubleTapEnabled
261	                isSingleTapEnabled
262	                style={styles.image}
263	                onLoad={handleImageLoad}
264	                onError={handleImageError}
265	                onSingleTap={handleSingleTap}
266	              />
267	            ) : null}
268	          </Block>
269	        </Block>
270	        <ImageInfoBottomSheet />
271	      </BottomSheetModalProvider>
272	    </Modal>
273	  );
274	};
275	
276	const styles = StyleSheet.create({
277	  image: {
278	    width: SCREEN_WIDTH,
279	    height: SCREEN_HEIGHT,
280	  },
281	  retryButton: {
282	    marginTop: 12,
283	    paddingVertical: 8,
284	    paddingHorizontal: 16,
285	  },
286	  infoIcon: {
287	    width: 24,
288	    height: 24,
289	  },
290	});
