25	export const VideoViewerModal: FC = () => {
26	  const [payload, setPayload] = useAtom(TimelineAtoms.videoViewerPayload);
27	  const [localUri, setLocalUri] = useState<string | null>(null);
28	  const [isLoading, setIsLoading] = useState(false);
29	  const [hasError, setHasError] = useState(false);
30	  const [showControls, setShowControls] = useState(true);
31	  const [naturalSize, setNaturalSize] = useState<{
32	    width: number;
33	    height: number;
34	  } | null>(null);
35	  const content = payload?.content ?? null;
36	  const event = payload?.event ?? null;
37	  const roomId = payload?.roomId ?? null;
38	  const visible = !!content;
39	  const hasEventContext = !!event && !!roomId;
40	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
41	
42	  const senderName = useMemo(() => {
43	    if (!event) return null;
44	    if (event.senderProfile.tag === ProfileDetails_Tags.Ready) {
