36	const getImageContent = (
37	  event: EventTimelineItem,
38	): ImageMessageContent | null => {
39	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
40	    const kind = event.content.inner.content.kind;
41	    if (kind?.tag === MsgLikeKind_Tags.Message) {
42	      const msgType = kind.inner.content.msgType;
43	      if (msgType?.tag === MessageType_Tags.Image) {
44	        return msgType.inner.content;
45	      }
46	    }
47	  }
48	  return null;
49	};
