51	export const ImageMessage: FC<Props> = ({
52	  roomId,
53	  event,
54	  isPreviousSameSender,
55	  onMemberPress,
56	}) => {
57	  const content = getImageContent(event);
58	  const [messageWidth, setMessageWidth] = useState(40);
59	  const originalWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
60	  const originalHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
61	  const scaleRatio = Math.min(MAX_MEDIA_WIDTH / originalWidth, 1);
62	  const targetWidth = Math.round(originalWidth * scaleRatio);
63	  const targetHeight = Math.round(originalHeight * scaleRatio);
64	  const [uri, setUri] = useState<string | null>(null);
65	  const [isLoading, setIsLoading] = useState(true);
66	  const isUser = event.isOwn;
67	  const sender = event.senderProfile;
68	  const senderId = event.sender;
69	  const caption = content?.caption;
70	  const seenByUsers = TimelineService.getReadReceiptUsers(event);
71	  const background = useMemo(() => {
72	    if (!caption) return "transparent";
73	    return isUser ? Colors.primary : Colors.message;
74	  }, [caption, isUser]);
75	  const setImageViewerPayload = useSetAtom(TimelineAtoms.imageViewerPayload);
76	
77	  const openImageViewer = useCallback(() => {
78	    if (!uri || isLoading) return;
79	    setImageViewerPayload({ uri, event, roomId });
80	  }, [uri, isLoading, setImageViewerPayload, event, roomId]);
81	
82	  useEffect(() => {
83	    if (!content) return;
84	    const mxcUrl = content.source.url();
85	    if (!mxcUrl) return;
86	
87	    const load = async () => {
88	      try {
89	        const resolved = await resolveEncryptedImage({
90	          cacheKey: mxcUrl,
91	          mediaSource: content.source,
92	          mimeType: content.info?.mimetype || "image/jpeg",
93	        });
94	        if (resolved) setUri(resolved);
95	      } catch (error) {
96	        console.error(error);
97	      } finally {
98	        setIsLoading(false);
99	      }
100	    };
101	
102	    load();
103	  }, [content]);
104	
105	  if (!content) return null;
106	
107	  return (
108	    <Block
109	      align={isUser ? "flex-end" : "flex-start"}
110	      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
111	    >
112	      <MessageSender
113	        sender={sender}
114	        senderId={senderId}
115	        isUser={isUser}
116	        isPreviousSameSender={isPreviousSameSender}
117	        onMemberPress={onMemberPress}
118	      />
119	      <Block flexDirection={isUser ? "row-reverse" : "row"}>
120	        <Block
121	          background={background}
122	          border={{ borderRadius: 12 }}
123	          paddings={caption ? [4, 4, 12] : 0}
124	          gap={8}
125	        >
126	          <Block
127	            background="transparent"
128	            border={{
129	              borderRadius: 12,
130	            }}
131	            align="center"
132	            overflow="hidden"
133	            width={targetWidth}
134	            height={targetHeight}
135	            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
136	          >
137	            {isLoading && (
138	              <Block
139	                absolute
140	                offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
141	                width="100%"
142	                height="100%"
143	                background={Colors.white10}
144	                align="center"
145	                justify="center"
146	                zIndex={1}
147	              >
148	                <Loading isFullScreen={false} />
149	              </Block>
150	            )}
151	            {uri && (
152	              <MessageLongPressWrapper
153	                event={event}
154	                content={getEventTextContent(event)}
155	                onFinalize={openImageViewer}
156	              >
157	                <Image
158	                  source={{ uri }}
159	                  width={targetWidth}
160	                  height={targetHeight}
161	                  resizeMode="contain"
162	                />
163	              </MessageLongPressWrapper>
164	            )}
165	          </Block>
166	
167	          {caption ? (
168	            <Block
169	              maxWidth={targetWidth}
170	              justify="space-between"
171	              flexDirection={isUser ? "row-reverse" : "row"}
172	              gap={{
173	                row: 4,
174	                col: 16,
175	              }}
176	              align="center"
177	              flex={{ flexWrap: "wrap" }}
178	              paddings={[0, 8]}
179	              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
180	            >
181	              <LinkifiedText body={caption} />
182	              <MessageTimestamp event={event} isUser={isUser} />
183	            </Block>
184	          ) : (
185	            <Block
186	              flexDirection={isUser ? "row" : "row-reverse"}
187	              gap={4}
188	              align="center"
189	              margins={{ marginLeft: isUser ? 0 : "auto" }}
190	            >
191	              <MessageTimestamp event={event} isUser={isUser} />
192	            </Block>
193	          )}
194	        </Block>
