15	import { Blurhash } from "react-native-blurhash";
16	import {
17	  LinkifiedText,
18	  MessageTimestamp,
19	  PinIndicator,
20	  SeenBy,
21	} from "shared/components";
22	import { MAX_MEDIA_WIDTH } from "shared/const";
23	import { Colors } from "shared/styles";
24	import { resolveEncryptedImage } from "shared/utils/encrypted-image-cache";
25	import { MessageLongPressWrapper } from "../message-long-press-wrapper";
26	import { MessageReactionsOverlay } from "../message-reactions-overlay";
27	import { MessageSender } from "../message-sender";
28	
29	interface Props {
30	  roomId: string;
31	  event: EventTimelineItem;
32	  isPreviousSameSender: boolean;
33	  onMemberPress?: (member: MemberDetailsPayload) => void;
34	}
35	
36	const getVideoContent = (
37	  event: EventTimelineItem,
38	): VideoMessageContent | null => {
39	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
40	    const kind = event.content.inner.content.kind;
41	    if (kind?.tag === MsgLikeKind_Tags.Message) {
42	      const msgType = kind.inner.content.msgType;
43	      if (msgType?.tag === MessageType_Tags.Video) {
44	        return msgType.inner.content;
45	      }
46	    }
47	  }
48	  return null;
49	};
50	
51	export const VideoMessage: FC<Props> = ({
52	  roomId,
53	  event,
54	  isPreviousSameSender,
55	  onMemberPress,
56	}) => {
57	  const content = getVideoContent(event);
58	  const [messageWidth, setMessageWidth] = useState(40);
59	  const thumbInfoWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
60	  const thumbInfoHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
61	  const originalWidth = thumbInfoWidth || Number(content?.info?.width) || 0;
62	  const originalHeight = thumbInfoHeight || Number(content?.info?.height) || 0;
63	  const scaleRatio = Math.min(MAX_MEDIA_WIDTH / originalWidth, 1);
64	  const targetWidth = Math.round(originalWidth * scaleRatio);
65	  const targetHeight = Math.round(originalHeight * scaleRatio);
66	  const [thumbnailUri, setThumbnailUri] = useState<string | null>(null);
67	  const isUser = event.isOwn;
68	  const sender = event.senderProfile;
69	  const senderId = event.sender;
70	  const caption = content?.caption;
71	  const blurhash = content?.info?.blurhash;
72	  const background = useMemo(() => {
73	    if (!caption) return "transparent";
74	    return isUser ? Colors.primary : Colors.message;
75	  }, [caption, isUser]);
76	  const seenByUsers = TimelineService.getReadReceiptUsers(event);
77	  const setVideoViewerPayload = useSetAtom(TimelineAtoms.videoViewerPayload);
78	
79	  const openVideoViewer = useCallback(() => {
80	    if (!content) return;
81	    setVideoViewerPayload({ content, event, roomId });
82	  }, [content, event, roomId, setVideoViewerPayload]);
83	
84	  useEffect(() => {
85	    const thumbSource = content?.info?.thumbnailSource;
86	    if (!thumbSource) return;
87	    const mxcUrl = thumbSource.url();
88	    if (!mxcUrl) return;
89	
90	    const load = async () => {
91	      try {
92	        const resolved = await resolveEncryptedImage({
93	          cacheKey: mxcUrl,
94	          mediaSource: thumbSource,
95	          mimeType: "image/jpeg",
96	        });
97	        if (resolved) setThumbnailUri(resolved);
98	      } catch (e) {
99	        console.error(e);
100	      }
101	    };
102	
103	    load();
104	  }, [content]);
105	
106	  if (!content) return null;
107	
108	  return (
109	    <Block
110	      align={isUser ? "flex-end" : "flex-start"}
111	      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
112	    >
113	      <MessageSender
114	        sender={sender}
115	        senderId={senderId}
116	        isUser={isUser}
117	        isPreviousSameSender={isPreviousSameSender}
118	        onMemberPress={onMemberPress}
119	      />
120	
121	      <Block flexDirection={isUser ? "row-reverse" : "row"}>
122	        <Block
123	          background={background}
124	          border={{ borderRadius: 12 }}
125	          paddings={caption ? [4, 4, 12] : 0}
126	          gap={8}
127	        >
128	          <Block
129	            background={Colors.white10}
130	            border={{ borderRadius: 12 }}
131	            align="center"
132	            overflow="hidden"
133	            width={targetWidth}
134	            height={targetHeight}
135	            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
136	          >
137	            <MessageLongPressWrapper
138	              event={event}
139	              content={getEventTextContent(event)}
140	              onFinalize={openVideoViewer}
141	            >
142	              {blurhash && !thumbnailUri && (
143	                <Blurhash
144	                  blurhash={blurhash}
145	                  style={{ width: targetWidth, height: targetHeight }}
146	                  resizeMode="cover"
147	                />
148	              )}
149	
150	              {thumbnailUri && (
151	                <Image
152	                  source={{ uri: thumbnailUri }}
153	                  style={{ width: targetWidth, height: targetHeight }}
154	                  resizeMode="cover"
155	                />
156	              )}
157	
158	              {/* Play button overlay */}
159	              <Block
160	                absolute
161	                offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
162	                zIndex={10}
163	                border={{ borderRadius: 12 }}
164	                align="center"
165	                justify="center"
166	                pointerEvents="none"
167	              >
168	                <Block
169	                  background={Colors.primary}
170	                  width={40}
171	                  height={40}
172	                  align="center"
173	                  justify="center"
174	                  border={{ borderRadius: 999 }}
175	                >
176	                  <Image
177	                    tintColor={Colors.white}
178	                    source={require("assets/icons/play.png")}
179	                  />
180	                </Block>
181	              </Block>
182	            </MessageLongPressWrapper>
183	          </Block>
184	
185	          {caption ? (
186	            <Block
187	              maxWidth={targetWidth}
188	              justify="space-between"
189	              flexDirection={isUser ? "row-reverse" : "row"}
190	              gap={{
191	                row: 4,
192	                col: 16,
193	              }}
194	              align="center"
195	              flex={{ flexWrap: "wrap" }}
196	              paddings={[0, 8]}
197	              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
198	            >
199	              <LinkifiedText body={caption} />
200	              <MessageTimestamp event={event} isUser={isUser} />
201	            </Block>
202	          ) : (
203	            <Block
204	              flexDirection={isUser ? "row" : "row-reverse"}
205	              gap={4}
206	              align="center"
207	              margins={{ marginLeft: isUser ? 0 : "auto" }}
208	            >
209	              <MessageTimestamp event={event} isUser={isUser} />
210	            </Block>
211	          )}
212	        </Block>
213	        <PinIndicator event={event} />
214	      </Block>
215	      <MessageReactionsOverlay event={event} roomId={roomId} isUser={isUser} />
216	      <SeenBy users={seenByUsers} messageWidth={messageWidth} isUser={isUser} />
217	    </Block>
218	  );
219	};
